type SchemaToTs<S> =
  S extends { type: "object"; properties: infer P extends Record<string, JsonSchema> }
    ? NullableResult<S, Simplify<{ [K in keyof P]: SchemaToTs<P[K]> }>>
    : S extends { type: "object" }
      ? NullableResult<S, Record<string, unknown>>
      : S extends { type: "array"; items: infer I extends JsonSchema }
        ? NullableResult<S, Array<SchemaToTs<I>>>
        : S extends { type: "string" }
          ? NullableResult<S, string>
          : S extends { type: "number" | "integer" }
            ? NullableResult<S, number>
            : S extends { type: "boolean" }
              ? NullableResult<S, boolean>
              : S extends { type: "null" }
                ? null
                : unknown;

type RestEndpointMap = typeof runtimeManifest.rest.endpoints;
type RestDraftbitApiEndpointKey = keyof RestEndpointMap;
type EndpointConfig<K extends RestDraftbitApiEndpointKey> = RestEndpointMap[K];
