export type DraftbitApiEndpointKey = RestDraftbitApiEndpointKey | GraphqlEndpointKey;

type RequiredQueryNames<T extends readonly QueryParamDescriptor[]> = Extract<
  T[number],
  { required: true }
>["name"];

type OptionalQueryNames<T extends readonly QueryParamDescriptor[]> = Exclude<
  T[number]["name"],
  RequiredQueryNames<T>
>;

type QueryInput<T extends readonly QueryParamDescriptor[]> = [T[number]] extends [never]
  ? undefined
  : Simplify<
      { [K in RequiredQueryNames<T>]: PrimitiveInput } & {
        [K in OptionalQueryNames<T>]?: PrimitiveInput | null | undefined;
      }
    >;

type PathInput<T extends readonly string[]> = [T[number]] extends [never]
  ? undefined
  : { [K in T[number]]: PrimitiveInput };

type BodyInput<E extends { requestBodyMode: "json" | "text" | null; requestBodySchema: JsonSchema | null }> =
  E["requestBodyMode"] extends "json"
    ? E["requestBodySchema"] extends JsonSchema
      ? SchemaToTs<E["requestBodySchema"]>
      : Record<string, unknown>
    : E["requestBodyMode"] extends "text"
      ? string
      : undefined;

type PathField<E extends { pathParams: readonly string[] }> = E["pathParams"][number] extends never
  ? { path?: undefined }
  : { path: PathInput<E["pathParams"]> };

type QueryField<E extends { queryParams: readonly QueryParamDescriptor[] }> =
  E["queryParams"][number] extends never ? { query?: undefined } : { query?: QueryInput<E["queryParams"]> };

type BodyField<E extends { requestBodyMode: "json" | "text" | null; requestBodySchema: JsonSchema | null }> =
  E["requestBodyMode"] extends null ? { body?: undefined } : { body?: BodyInput<E> };

