export class DraftbitApiError extends Error {
  endpointKey: DraftbitApiEndpointKey;
  kind: "rest" | "graphql";

  constructor({
    kind,
    endpointKey,
    message,
  }: {
    kind: "rest" | "graphql";
    endpointKey: DraftbitApiEndpointKey;
    message: string;
  }) {
    super(message);
    this.name = "DraftbitApiError";
    this.kind = kind;
    this.endpointKey = endpointKey;
  }
}

